class AlienaliasMatchingStrategy {
    get alienAliasService() {
        return this.es.getEntityCollectionService('AlienAlias');
    }
    constructor(siteName, es, router) {
        this.siteName = siteName;
        this.es = es;
        this.router = router;
    }
    match(state) {
        const matchPathQuery = 'path=' + state.url.substr(1).split('/').reduce((p, c, i) => [...p, i === 0 ? `/${c}` : `${p[i - 1]}/${c}`], []).map(p => this.encodePathComponent(p)).join('&path=') + `&site=${encodeURIComponent(`{"term":{"site.keyword":{"value":"${this.siteName}"}}}`)}`;
        return this.alienAliasService.getWithQuery(matchPathQuery).pipe(catchError(e => {
            return of([]);
        }), map(aa => aa.reduce((p, c) => p === undefined ? c : p.path.split('/').length < c.path.split('/').length ? c : p, undefined)), map(m => !!m), defaultIfEmpty(false));
    }
    encodePathComponent(v) {
        return `{"term":{"path.keyword":{"value":"${v}"}}}`;
    }
}

class AlienaliasRedirectHandler {
    get alienAliasService() {
        return this.es.getEntityCollectionService('AlienAlias');
    }
    constructor(siteName, es, router) {
        this.siteName = siteName;
        this.es = es;
        this.router = router;
    }
    redirect(route, state) {
        if (state.url.indexOf('pages') > -1) {
            console.log(`redirect: ${state.url}`);
            this.router.navigateByUrl(state.url);
        }
        else {
            const matchPathQuery = 'path=' + state.url.substr(1).split('/').reduce((p, c, i) => [...p, i === 0 ? `/${c}` : `${p[i - 1]}/${c}`], []).map(p => this.encodePathComponent(p)).join('&path=') + `&site=${encodeURIComponent(`{"term":{"site.keyword":{"value":"${this.siteName}"}}}`)}`;
            this.alienAliasService.getWithQuery(matchPathQuery).pipe(map(aa => aa.reduce((p, c) => p === undefined ? c : p.path.split('/').length < c.path.split('/').length ? c : p, undefined)), map(a => {
                const argPath = state.url.substr(1).split('/').slice(a.path.split('/').length - 1).join('/');
                return [a, argPath];
            })).subscribe(([a, argPath]) => {
                // this.router.onSameUrlNavigation.reload;
                // this.router.navigate(['reload']);
                console.log(`nagigvate to: ${a.path}${argPath === '' ? '' : `/${argPath}`}?${qs.stringify(route.queryParams)}`);
                this.router.navigateByUrl(`${a.path}${argPath === '' ? '' : `/${argPath}`}?${qs.stringify(route.queryParams)}`, /* Removed unsupported properties by Angular migration: queryParams, fragment. */ {});
                // this.router.navigateByUrl(`/pages/panelpage/${panelPage.id}${argPath === '' ? '' : `/${argPath}`}?${qs.stringify(route.queryParams)}`, {queryParams: { ...((route as ActivatedRouteSnapshot).queryParams) }, fragment: (route as ActivatedRouteSnapshot).fragment })
            });
        }
    }
    encodePathComponent(v) {
        return `{"term":{"path.keyword":{"value":"${v}"}}}`;
    }
}

const alienaliasFactory = (siteName, es, router) => {
    const loadingStrategy = new AlienaliasLoadingStrategy(siteName, es, router);
    const matchingStrategy = new AlienaliasMatchingStrategy(siteName, es, router);
    const redirectHandler = new AlienaliasRedirectHandler(siteName, es, router);
    return new AlienaliasPlugin({ id: 'module', title: 'module', loadingStrategy, matchingStrategy, redirectHandler });
};

